// Without "wavelength units", values above 100 are taken as nanometres.
const toMicrometres = (v) => (v > 100 ? v / 1000 : v);

// Band centres and widths from an ENVI header, in micrometres.
export function bandsOf(header) {
  const unit = header['wavelength units']?.toLowerCase();
  if (unit === 'nanometers') return { centres: header.wavelength.map((v) => v / 1000), fwhm: header.fwhm?.map((v) => v / 1000) };
  if (unit === 'micrometers') return { centres: header.wavelength, fwhm: header.fwhm };
  return { centres: header.wavelength.map(toMicrometres), fwhm: header.fwhm?.map(toMicrometres) };
}
